\documentclass[a4paper]{article}

% Basic packages
% Español (México) con XeLaTeX: fontspec para fuentes Unicode, polyglossia
% para la división silábica y los nombres del documento en la variante mexicana.
\usepackage{fontspec}
\usepackage{polyglossia}
\setdefaultlanguage[variant=mexican]{spanish}
% Los nombres chinos van como «pinyin (original)»: xeCJK da a los caracteres
% Han su propia fuente; sin ella XeLaTeX los omite con un aviso.
\usepackage{xeCJK}
\setCJKmainfont{FandolSong-Regular.otf}
% polyglossia no traduce los nombres de listings.
\AtBeginDocument{\providecommand{\lstlistingname}{}\renewcommand{\lstlistingname}{Listado}%
  \providecommand{\lstlistlistingname}{}\renewcommand{\lstlistlistingname}{Índice de listados}}
\usepackage{amsmath, amssymb}
\usepackage{graphicx}
\usepackage[margin=2.5cm]{geometry}
\usepackage[most]{tcolorbox}
\usepackage{etoolbox}
\usepackage{listings}
\usepackage{hyperref}
\usepackage{booktabs}
\usepackage{subcaption}
\usepackage{float}
\usepackage{array}

% Highlight boxes
\newtcolorbox{knowledgebox}[1]{
    enhanced, colback=blue!5!white, colframe=blue!75!black, colbacktitle=blue!75!black,
    coltitle=white, fonttitle=\bfseries, title={#1}, attach boxed title to top left={yshift=-2mm, xshift=2mm},
    boxrule=1pt, sharp corners
}

\newtcolorbox{importantbox}[1]{
    enhanced, colback=yellow!10!white, colframe=yellow!80!black, colbacktitle=yellow!80!black,
    coltitle=black, fonttitle=\bfseries, title={#1}, sharp corners
}

\newtcolorbox{warningbox}[1]{
    enhanced, colback=red!5!white, colframe=red!75!black, colbacktitle=red!75!black,
    coltitle=white, fonttitle=\bfseries, title={#1}, sharp corners
}

% Listings
\lstset{
    language=Python,
    basicstyle=\ttfamily\small,
    keywordstyle=\color{blue},
    stringstyle=\color{red!60!black},
    commentstyle=\color{green!60!black},
    breaklines=true,
    frame=single,
    numbers=left,
    numberstyle=\tiny\color{gray},
    captionpos=b,
    extendedchars=true
}

% Front-page metadata
\newcommand{\notetitle}{Jensen Huang: NVIDIA 的系统级 AI 战略与产业化路径}
\newcommand{\noteauthors}{基于 Jensen Huang 访谈内容整理}
\newcommand{\notedate}{2026-04-02}
\newcommand{\videochannel}{Lex Fridman}
\newcommand{\videopublishdate}{2026-03-23}
\newcommand{\videoduration}{2h 25m}
\newcommand{\videourl}{https://www.youtube.com/watch?v=vif8NQcjVf0}
\newcommand{\videocoverpath}{cover.jpg}
\newcommand{\repourl}{https://github.com/hqhq1025/ai-course-notes}


% Footer with repo info
\usepackage{fancyhdr}
\pagestyle{fancy}
\fancyhf{}
\fancyfoot[C]{\thepage}
\fancyfoot[R]{\footnotesize\color{gray}\href{\repourl}{AI Course Notes}}
\renewcommand{\headrulewidth}{0pt}
\renewcommand{\footrulewidth}{0pt}

\begin{document}

